<?php

declare(strict_types=1);

/*
 * Generates the icon set for both renderers from resources/icons/*.svg.
 *
 * The set used to be written out twice — a PHP array inside the Blade
 * component and a TypeScript map in the core package — with a test holding the
 * two in step. One source and a generator removes the class of bug the test was
 * there to catch, and makes adding an icon a matter of dropping in an SVG.
 *
 *     php bin/build-icons.php [--check]
 *
 * --check exits non-zero if the generated files are out of date, which is what
 * CI runs.
 */

$root = dirname(__DIR__);
$source = $root.'/resources/icons';
$check = in_array('--check', $argv, true);

$files = glob($source.'/*.svg');
sort($files);

if ($files === false || $files === []) {
    fwrite(STDERR, "No icons found in {$source}.\n");
    exit(1);
}

$icons = [];

foreach ($files as $file) {
    $name = basename($file, '.svg');

    if (preg_match('/^[a-z][a-z0-9-]*$/', $name) !== 1) {
        fwrite(STDERR, "Icon name [{$name}] must be lower-case kebab-case.\n");
        exit(1);
    }

    $svg = (string) file_get_contents($file);

    if (! str_contains($svg, 'viewBox="0 0 24 24"')) {
        fwrite(STDERR, "Icon [{$name}] must be drawn on a 24x24 viewBox.\n");
        exit(1);
    }

    // Only the inner geometry travels; the <svg> wrapper is the component's,
    // so stroke width and colour stay under the design system's control.
    $inner = preg_replace('/^.*?<svg[^>]*>|<\/svg>.*$/s', '', $svg);
    $inner = trim(preg_replace('/\s+/', ' ', (string) $inner) ?? '');
    $inner = str_replace('> <', '><', $inner);

    if ($inner === '') {
        fwrite(STDERR, "Icon [{$name}] is empty.\n");
        exit(1);
    }

    foreach (['fill=', 'stroke=', 'stroke-width='] as $attribute) {
        if (str_contains($inner, $attribute)) {
            fwrite(STDERR, "Icon [{$name}] sets [{$attribute}]; that belongs to the component, not the icon.\n");
            exit(1);
        }
    }

    $icons[$name] = $inner;
}

$php = "<?php\n\ndeclare(strict_types=1);\n\n"
    ."namespace MyEyes\\Support;\n\n"
    ."/**\n * The my-eyes icon set.\n *\n"
    ." * Generated by bin/build-icons.php from resources/icons — do not edit by\n"
    ." * hand. Add an icon by dropping a 24x24 SVG in there and running the script.\n */\n"
    ."final class Icons\n{\n"
    ."    /** @var array<string, string> */\n"
    ."    public const PATHS = [\n";

foreach ($icons as $name => $inner) {
    $php .= "        '{$name}' => '".str_replace("'", "\\'", $inner)."',\n";
}

$php .= "    ];\n}\n";

$ts = "/*\n * The my-eyes icon set.\n *\n"
    ." * Generated by bin/build-icons.php from resources/icons — do not edit by\n"
    ." * hand. Add an icon by dropping a 24x24 SVG in there and running the script.\n */\n\n"
    ."export type BundledIconName =\n";

foreach (array_keys($icons) as $name) {
    $ts .= "    | '{$name}'\n";
}

$ts .= "\nexport const bundledIcons: Record<BundledIconName, string> = {\n";

foreach ($icons as $name => $inner) {
    $ts .= "    '{$name}': '".str_replace("'", "\\'", $inner)."',\n";
}

$ts .= "}\n";

$targets = [
    $root.'/src/Support/Icons.php' => $php,
    $root.'/packages/core/src/bundled-icons.ts' => $ts,
];

$stale = [];

foreach ($targets as $path => $contents) {
    $current = is_file($path) ? file_get_contents($path) : null;

    if ($current === $contents) {
        continue;
    }

    if ($check) {
        $stale[] = str_replace($root.'/', '', $path);

        continue;
    }

    file_put_contents($path, $contents);
}

if ($check && $stale !== []) {
    fwrite(STDERR, "Out of date, run `php bin/build-icons.php`:\n  ".implode("\n  ", $stale)."\n");
    exit(1);
}

$count = count($icons);
echo $check ? "Icons are up to date ({$count}).\n" : "Generated {$count} icons.\n";
